#include "bench_common.hpp"
#include <iostream>
int main(int argc,char**argv){try{auto o=bench::parse(argc,argv);std::ofstream c(o.csv);bench::header(c);const bench::range rr[]={{"[-pi/2,pi/2]",-toltrig::half_pi,toltrig::half_pi},{"[-pi,pi]",-toltrig::pi,toltrig::pi},{"[-100,100]",-100,100},{"[-1e6,1e6]",-1e6,1e6}};for(int i=0;i<4;++i){auto v=bench::inputs(rr[i],o.samples,o.seed+i);auto base=bench::median_ms(v,[](double x){return std::cos(x);},o);bench::row(c,o,"full",rr[i],"std_cos",base,base);auto emit=[&](const char*n,bench::fn f){auto ms=bench::median_ms(v,f,o);bench::row(c,o,"full",rr[i],n,ms,base,bench::error(v,f));};emit("toltrig_cos_bounded_n7",toltrig::cos_bounded_n7);emit("toltrig_cos_bounded_n8",toltrig::cos_bounded_n8);emit("toltrig_cos_remainder_n7",toltrig::cos_remainder_n7);emit("toltrig_cos_remainder_n8",toltrig::cos_remainder_n8);if(i==0){emit("toltrig_cos_reduced_n7",toltrig::cos_reduced_n7);emit("toltrig_cos_reduced_n8",toltrig::cos_reduced_n8);}}std::cout<<"CSV written to "<<o.csv<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
